PC = np.array([0.1145, -0.4356]); PHI = 9.25
res = []
for closing in [PHI, PHI+60, PHI+120]:
    for az in [closing - 90, closing + 90]:
        az = (az + 180) % 360 - 180
        for tilt in [60, 65, 70, 75, 80, 85]:
            z = 0.110
            p = gpose([PC[0], PC[1], z], closing_deg=closing, az_deg=az, tilt_deg=tilt)
            r = ep.ik(p, max=8)
            if not r["reachable"]:
                continue
            sols = [s for s in r["solutions"] if s["pos_err_mm"] < 2 and s["rot_err_deg"] < 2]
            if not sols: continue
            cks = ep.check_batch([s["q"] for s in sols], held=False)
            for s, ck in zip(sols, cks):
                arm_c = [(k["link"], k["obstacle"], round(k["clearance_m"],3)) for k in ck["contacts"] if k["link"] not in GRIP_LINKS]
                res.append((closing, az, tilt, s["limit_margin_rad"], arm_c, s["q"]))
for closing, az, tilt, m, arm_c, q in res:
    print("cl %.1f az %.1f tilt %d margin %.2f" % (closing, az, tilt, m), "ARM:", arm_c[:3], "q", np.round(q,2))

